    public class PokemonSprite
    {
        public string Key;
        public string NameKo;
        public double ScaleFactor;
        public bool FacesRight;   // 원본 그림이 오른쪽을 보고 있는지
        public bool Hops;         // 걷지 않고 폴짝 뛰어 다니는지
